package set_segment

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_segment"
	command.Identifiers = []string{"set-segment"}
	command.Category = "Server System"
	command.Help = "Rewrite one declared segment of a route's path"
	command.LongDescription = "Rewrites one segment of the route's path in place and runs build. It is add-segment applied to a declaration that already exists: the keys given are written over the ones there, --clear takes one off, and the result goes through the same constructor — so editing a segment and declaring one leave the same bytes. --identifier makes the segment a literal, whatever it was before; every other key edits a capture."
	command.Examples = []string{"set-segment tenant --route create-user --type int --description 'the tenant id'"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route (identifier or package name) the segment is declared on",
			Examples:    []string{"set-segment tenant --route create-user"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--route"},
		},
		{
			Id:          "rename",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the name the captured segment answers to from now on",
			Examples:    []string{"set-segment tenant --route create-user --rename account"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--rename"},
		},
		{
			Id:          "identifier",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "make the segment a literal spelling this, whatever it was before",
			Examples:    []string{"set-segment tenant --route create-user --identifier /accounts"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--identifier"},
		},
		{
			Id:          "type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the value type of the capture: string, boolean, int or float",
			Examples:    []string{"set-segment tenant --route create-user --type int"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--type"},
		},
		{
			Id:          "description",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "help text shown for the capture",
			Examples:    []string{"set-segment tenant --route create-user --description 'the tenant the user belongs to'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--description"},
		},
		{
			Id:          "array",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "make the capture take every segment left in the path (last segment only)",
			Examples:    []string{"set-segment rest --route serve-file --array"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--array"},
		},
		{
			Id:          "min",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "smallest accepted value (int/float only)",
			Examples:    []string{"set-segment page --route list-users --type int --min 1"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--min"},
		},
		{
			Id:          "max",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "largest accepted value (int/float only)",
			Examples:    []string{"set-segment page --route list-users --type int --max 50"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--max"},
		},
		{
			Id:          "example",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a value the capture takes, for the docs (repeatable; appended)",
			Examples:    []string{"set-segment tenant --route create-user --example acme"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--example"},
		},
		{
			Id:          "clear",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a key to take off again: description, examples, required, array, min or max (repeatable)",
			Examples:    []string{"set-segment page --route list-users --clear max"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--clear"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
		{
			Id:          "starts-with",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "spell a literal segment the path only has to begin with, so the route answers every path under it",
			Examples:    []string{"set-segment --route logger --starts-with /api"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--starts-with"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the segment to edit: a capture by its name, a literal by the identifier it spells",
			Examples:    []string{"set-segment tenant --route create-user --type int"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
